-- Reviewed senior batch 025; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":5031,"word":"gland","meaning":"腺體","example":"The class examined a plastic model of a salivary gland.","example_zh":"全班觀察了唾液腺的塑膠模型。","original_meaning":"腺體","original_example":"The thyroid gland.","original_example_zh":"甲狀腺。"},{"source_id":5032,"word":"intestine","meaning":"腸","example":"The teacher pointed to the intestine in the digestive system model.","example_zh":"老師指出消化系統模型中的腸道。","original_meaning":"腸","original_example":"The small intestine.","original_example_zh":"小腸。"},{"source_id":5033,"word":"liver","meaning":"肝臟","example":"The student identified the liver on the classroom model.","example_zh":"學生在教室模型上辨認出肝臟。","original_meaning":"肝臟","original_example":"Liver disease.","original_example_zh":"肝病。"},{"source_id":5034,"word":"kidney","meaning":"腎臟","example":"The model showed a kidney beside the other organs.","example_zh":"模型展示了其他器官旁的一顆腎臟。","original_meaning":"腎臟","original_example":"Kidney failure.","original_example_zh":"腎衰竭。"},{"source_id":5035,"word":"lung","meaning":"肺","example":"The teacher lifted a plastic lung from the teaching kit.","example_zh":"老師從教學套件中拿起一個塑膠肺模型。","original_meaning":"肺","original_example":"Lung cancer.","original_example_zh":"肺癌。"},{"source_id":5036,"word":"diabetes","meaning":"糖尿病","example":"The nurse prepared a lesson about diabetes.","example_zh":"護理師準備了一堂關於糖尿病的課。","original_meaning":"糖尿病","original_example":"Type 2 diabetes.","original_example_zh":"第二型糖尿病。"},{"source_id":5037,"word":"asthma","meaning":"氣喘","example":"The health class discussed how asthma can affect daily life.","example_zh":"健康課討論氣喘如何影響日常生活。","original_meaning":"氣喘","original_example":"Suffer from asthma.","original_example_zh":"患有哮喘。"},{"source_id":5038,"word":"arthritis","meaning":"關節炎","example":"The lecturer used a joint model to explain arthritis.","example_zh":"講師用關節模型解釋關節炎。","original_meaning":"關節炎","original_example":"Chronic arthritis.","original_example_zh":"慢性關節炎。"},{"source_id":5039,"word":"dementia","meaning":"失智","example":"The students learned about support for families affected by dementia.","example_zh":"學生了解了如何支持受失智症影響的家庭。","original_meaning":"失智","original_example":"Early-onset dementia.","original_example_zh":"早發性失智症。"},{"source_id":5040,"word":"obesity","meaning":"肥胖","example":"The library hosted a public lecture about obesity.","example_zh":"圖書館舉辦了一場關於肥胖的公開講座。","original_meaning":"肥胖","original_example":"Childhood obesity.","original_example_zh":"兒童肥胖。"},{"source_id":5041,"word":"insomnia","meaning":"失眠","example":"Her diary described several nights of insomnia.","example_zh":"她的日記描述了好幾晚的失眠。","original_meaning":"失眠","original_example":"Chronic insomnia.","original_example_zh":"慢性失眠。"},{"source_id":5042,"word":"migraine","meaning":"偏頭痛","example":"He told the doctor that a migraine had interrupted his work.","example_zh":"他告訴醫師，偏頭痛打斷了他的工作。","original_meaning":"偏頭痛","original_example":"A severe migraine.","original_example_zh":"一場劇烈的偏頭痛。"},{"source_id":5043,"word":"stroke","meaning":"中風","example":"The medical students attended a lecture about stroke.","example_zh":"醫學生參加了一堂關於中風的講課。","original_meaning":"中風","original_example":"Suffer a stroke.","original_example_zh":"中風。"},{"source_id":5044,"word":"tumor","meaning":"腫瘤","example":"The biology book included a chapter about tumor research.","example_zh":"生物學書籍有一章介紹腫瘤研究。","original_meaning":"腫瘤","original_example":"A brain tumor.","original_example_zh":"腦瘤。"},{"source_id":5045,"word":"infection","meaning":"感染","example":"The laboratory team studied a sample for signs of infection.","example_zh":"實驗室團隊研究樣本是否有感染跡象。","original_meaning":"感染","original_example":"A viral infection.","original_example_zh":"病毒感染。"},{"source_id":5046,"word":"inflammation","meaning":"發炎","example":"The lecturer explained inflammation with a simple model.","example_zh":"講師用簡單模型解釋發炎。","original_meaning":"發炎","original_example":"Reduce inflammation.","original_example_zh":"減輕發炎。"},{"source_id":5047,"word":"painkiller","meaning":"止痛藥","example":"The pharmacist checked the painkiller's label before answering her question.","example_zh":"藥師先查看止痛藥的標籤，再回答她的問題。","original_meaning":"止痛藥","original_example":"Take a painkiller.","original_example_zh":"服用止痛藥。"},{"source_id":5048,"word":"symphony","meaning":"交響曲","example":"The musicians rehearsed a symphony for the evening concert.","example_zh":"樂手們為晚間音樂會排練一首交響曲。","original_meaning":"交響曲","original_example":"A symphony orchestra.","original_example_zh":"一支交響樂團。"},{"source_id":5049,"word":"ballet","meaning":"芭蕾舞","example":"The ballet ended with a graceful group dance.","example_zh":"這齣芭蕾舞劇以優雅的群舞結束。","original_meaning":"芭蕾舞","original_example":"A ballet dancer.","original_example_zh":"一位芭蕾舞者。"},{"source_id":5050,"word":"orchestra","meaning":"管弦樂團","example":"The orchestra tuned its instruments before the conductor arrived.","example_zh":"指揮抵達前，管弦樂團先調整樂器音準。","original_meaning":"管弦樂團","original_example":"A full orchestra.","original_example_zh":"完整的管弦樂團。"},{"source_id":5051,"word":"soprano","meaning":"女高音","example":"The soprano sang a clear, soaring melody.","example_zh":"女高音唱出清亮高昂的旋律。","original_meaning":"女高音","original_example":"A soprano voice.","original_example_zh":"女高音。"},{"source_id":5052,"word":"gallery","meaning":"畫廊","example":"The gallery displayed paintings by local artists.","example_zh":"畫廊展出本地藝術家的畫作。","original_meaning":"畫廊","original_example":"An art gallery.","original_example_zh":"一間藝廊。"},{"source_id":5053,"word":"sculptor","meaning":"雕塑家","example":"The sculptor shaped the clay into a small bird.","example_zh":"雕塑家把黏土塑成一隻小鳥。","original_meaning":"雕塑家","original_example":"A famous sculptor.","original_example_zh":"一位著名雕塑家。"},{"source_id":5054,"word":"prose","meaning":"散文","example":"She wrote a short piece of prose about her hometown.","example_zh":"她寫了一篇關於家鄉的短篇散文。","original_meaning":"散文","original_example":"Write in prose.","original_example_zh":"用散文寫作。"},{"source_id":5055,"word":"verse","meaning":"詩句","example":"The teacher read a verse from the poem aloud.","example_zh":"老師朗讀了詩中的一段詩句。","original_meaning":"詩句","original_example":"A verse of poetry.","original_example_zh":"一首詩。"},{"source_id":5056,"word":"stanza","meaning":"詩節","example":"Each stanza gave the poem a new image.","example_zh":"每一詩節都為這首詩帶來新的意象。","original_meaning":"詩節","original_example":"The first stanza.","original_example_zh":"第一節。"},{"source_id":5057,"word":"protagonist","meaning":"主角","example":"The protagonist began her journey in a quiet village.","example_zh":"女主角在寧靜村莊展開旅程。","original_meaning":"主角","original_example":"The story protagonist.","original_example_zh":"故事的主角。"},{"source_id":5058,"word":"narrator","meaning":"敘事者","example":"The narrator described the village before introducing the characters.","example_zh":"敘事者先描述村莊，再介紹角色。","original_meaning":"敘事者","original_example":"A first-person narrator.","original_example_zh":"第一人稱敘述者。"},{"source_id":5059,"word":"irony","meaning":"反諷","example":"The irony was that the expert on punctuality arrived late.","example_zh":"諷刺的是，研究守時的專家竟然遲到。","original_meaning":"反諷","original_example":"Dramatic irony.","original_example_zh":"戲劇性諷刺。"},{"source_id":5060,"word":"parody","meaning":"模仿","example":"The students performed a playful parody of a detective story.","example_zh":"學生表演了一齣逗趣的偵探故事模仿劇。","original_meaning":"模仿","original_example":"A clever parody.","original_example_zh":"一則機智的諷刺作品。"},{"source_id":5061,"word":"cruise","meaning":"郵輪旅行","example":"They enjoyed a short cruise around the island.","example_zh":"他們享受了一趟環島短程郵輪之旅。","original_meaning":"郵輪","original_example":"A Caribbean cruise.","original_example_zh":"加勒比海郵輪之旅。"},{"source_id":5062,"word":"cuisine","meaning":"料理；菜系","example":"The festival introduced visitors to several kinds of regional cuisine.","example_zh":"節慶讓訪客認識多種地方菜系。","original_meaning":"料理；菜系","original_example":"The exchange students cooked dishes from their home cuisine for the festival.","original_example_zh":"交換學生為文化節烹調家鄉料理。"},{"source_id":5063,"word":"herb","meaning":"草本植物","example":"She planted a fragrant herb beside the kitchen window.","example_zh":"她在廚房窗邊種了一株芳香草本植物。","original_meaning":"草本植物","original_example":"Fresh herbs.","original_example_zh":"新鮮香草。"},{"source_id":5064,"word":"spice","meaning":"香料","example":"The cook added a pinch of spice to the soup.","example_zh":"廚師在湯裡加了一小撮香料。","original_meaning":"香料","original_example":"Exotic spices.","original_example_zh":"異國香料。"},{"source_id":5065,"word":"irrigate","meaning":"灌溉","example":"The farmers used channels to irrigate the fields.","example_zh":"農民用水渠灌溉田地。","original_meaning":"灌溉","original_example":"Irrigate the fields.","original_example_zh":"灌溉田地。"},{"source_id":5066,"word":"fertilizer","meaning":"肥料","example":"The gardener stored the fertilizer in a dry shed.","example_zh":"園丁把肥料存放在乾燥的棚屋裡。","original_meaning":"肥料","original_example":"Chemical fertilizer.","original_example_zh":"化學肥料。"},{"source_id":5067,"word":"organic","meaning":"有機的","example":"The market sold organic vegetables from a nearby farm.","example_zh":"市場販售附近農場出產的有機蔬菜。","original_meaning":"有機的","original_example":"The market sells organic vegetables grown on farms nearby.","original_example_zh":"市場販售附近農場種植的有機蔬菜。"},{"source_id":5068,"word":"infantry","meaning":"步兵","example":"The museum exhibit explained how infantry traveled on foot.","example_zh":"博物館展覽說明步兵如何徒步行進。","original_meaning":"步兵","original_example":"The infantry division.","original_example_zh":"步兵師。"},{"source_id":5069,"word":"artillery","meaning":"砲兵；火砲","example":"The museum placed an old artillery piece behind a barrier.","example_zh":"博物館把一門古老火砲放在圍欄後方。","original_meaning":"砲兵","original_example":"Heavy artillery.","original_example_zh":"重型火砲。"},{"source_id":5070,"word":"regiment","meaning":"團","example":"The historian traced the regiment's journey on a map.","example_zh":"歷史學家在地圖上追溯這個團的行軍路線。","original_meaning":"團","original_example":"A military regiment.","original_example_zh":"一個軍團。"},{"source_id":5071,"word":"trench","meaning":"壕溝","example":"The archaeological team examined an old trench.","example_zh":"考古團隊勘查了一條古老壕溝。","original_meaning":"壕溝","original_example":"Trench warfare.","original_example_zh":"塹壕戰。"},{"source_id":5072,"word":"ceasefire","meaning":"停火","example":"The ceasefire allowed aid workers to deliver supplies.","example_zh":"停火讓援助人員得以運送物資。","original_meaning":"停火","original_example":"Declare a ceasefire.","original_example_zh":"宣布停火。"},{"source_id":5073,"word":"conscript","meaning":"被徵召者","example":"The diary followed a young adult conscript during training.","example_zh":"日記記述了一位成年年輕被徵召者的受訓生活。","original_meaning":"被徵召者","original_example":"Military conscripts.","original_example_zh":"軍事徵召人員。"},{"source_id":5074,"word":"startup","meaning":"新創公司","example":"The startup designed a reusable lunch container.","example_zh":"這家新創公司設計了可重複使用的午餐盒。","original_meaning":"新創公司","original_example":"A tech startup.","original_example_zh":"科技新創公司。"},{"source_id":5075,"word":"syllabus","meaning":"課程大綱","example":"The teacher handed out the syllabus on the first day.","example_zh":"老師在第一天發下課程大綱。","original_meaning":"課程大綱","original_example":"Read the syllabus.","original_example_zh":"閱讀課程大綱。"},{"source_id":5076,"word":"subconscious","meaning":"潛意識的","example":"The writer explored a character's subconscious fears through dreams.","example_zh":"作家透過夢境探索角色潛意識中的恐懼。","original_meaning":"潛意識的","original_example":"A subconscious desire.","original_example_zh":"潛意識的渴望。"},{"source_id":5077,"word":"phobia","meaning":"恐懼症","example":"The student researched how a phobia differs from ordinary fear.","example_zh":"學生研究恐懼症與一般害怕有何不同。","original_meaning":"恐懼症","original_example":"A common phobia.","original_example_zh":"一種常見的恐懼症。"},{"source_id":5078,"word":"existentialism","meaning":"存在主義","example":"The philosophy class discussed freedom and responsibility in existentialism.","example_zh":"哲學課討論存在主義中的自由與責任。","original_meaning":"存在主義","original_example":"French existentialism.","original_example_zh":"法國存在主義。"},{"source_id":5079,"word":"utilitarianism","meaning":"功利主義","example":"The class debated a public policy using utilitarianism.","example_zh":"全班運用功利主義辯論一項公共政策。","original_meaning":"功利主義","original_example":"The theory of utilitarianism.","original_example_zh":"功利主義理論。"},{"source_id":5080,"word":"abide","meaning":"遵守","example":"All visitors must abide by the museum's rules.","example_zh":"所有訪客都必須遵守博物館規定。","original_meaning":"遵守","original_example":"Abide by the rules.","original_example_zh":"遵守規則。"},{"source_id":5081,"word":"accrue","meaning":"累積","example":"Small savings can accrue over many months.","example_zh":"小額儲蓄可以在數個月裡逐漸累積。","original_meaning":"累積","original_example":"Interest accrues.","original_example_zh":"利息會累積。"},{"source_id":5082,"word":"acquit","meaning":"無罪開釋","example":"The jury voted to acquit the defendant after reviewing the evidence.","example_zh":"陪審團檢視證據後投票判定被告無罪。","original_meaning":"無罪開釋","original_example":"Acquitted of all charges.","original_example_zh":"所有指控均獲判無罪。"},{"source_id":5083,"word":"adjourn","meaning":"休會","example":"The chair decided to adjourn the meeting until Friday.","example_zh":"主席決定把會議延至星期五再開。","original_meaning":"休會","original_example":"Adjourn the meeting.","original_example_zh":"休會。"},{"source_id":5084,"word":"amass","meaning":"積累","example":"The collector managed to amass hundreds of old postcards.","example_zh":"收藏家設法收集了數百張老明信片。","original_meaning":"積累","original_example":"Amass a fortune.","original_example_zh":"積攢一筆財富。"},{"source_id":5085,"word":"barter","meaning":"以物易物","example":"The neighbors agreed to barter apples for fresh bread.","example_zh":"鄰居同意用蘋果交換新鮮麵包。","original_meaning":"以物易物","original_example":"Barter goods.","original_example_zh":"以物易物。"},{"source_id":5086,"word":"capitalize","meaning":"利用","example":"The team hoped to capitalize on its strong design skills.","example_zh":"團隊希望善用自身優秀的設計能力。","original_meaning":"利用","original_example":"Capitalize on the opportunity.","original_example_zh":"把握機會。"},{"source_id":5087,"word":"censor","meaning":"審查","example":"The fictional government tried to censor the newspaper.","example_zh":"虛構政府試圖審查這份報紙。","original_meaning":"審查","original_example":"Censor the press.","original_example_zh":"審查新聞媒體。"},{"source_id":5088,"word":"compile","meaning":"編纂","example":"The volunteers helped compile a guide to local walking trails.","example_zh":"志工協助編纂本地步道指南。","original_meaning":"編纂","original_example":"Compile data.","original_example_zh":"彙整資料。"},{"source_id":5089,"word":"comprehend","meaning":"理解","example":"She used a model to comprehend the bridge's structure.","example_zh":"她利用模型理解這座橋的結構。","original_meaning":"理解","original_example":"Hard to comprehend.","original_example_zh":"難以理解。"},{"source_id":5090,"word":"congregate","meaning":"聚集","example":"Visitors began to congregate near the museum entrance.","example_zh":"訪客開始聚集在博物館入口附近。","original_meaning":"聚集","original_example":"People congregated.","original_example_zh":"人們聚集在一起。"},{"source_id":5091,"word":"dismantle","meaning":"拆解","example":"The technician carefully dismantled the broken desk lamp.","example_zh":"技術人員小心拆解壞掉的檯燈。","original_meaning":"拆解","original_example":"Dismantle the bomb.","original_example_zh":"拆解炸彈。"},{"source_id":5092,"word":"disseminate","meaning":"散播","example":"The library used leaflets to disseminate information about its new services.","example_zh":"圖書館用傳單傳播新服務的資訊。","original_meaning":"散播","original_example":"Disseminate information.","original_example_zh":"傳播資訊。"},{"source_id":5093,"word":"eject","meaning":"驅逐","example":"The referee chose to eject the player for repeated misconduct.","example_zh":"裁判決定將屢次行為不當的球員逐出場。","original_meaning":"驅逐","original_example":"Eject the passenger.","original_example_zh":"請乘客下車。"},{"source_id":5094,"word":"exterminate","meaning":"滅絕","example":"The museum explained how a disease could exterminate an isolated insect population.","example_zh":"博物館說明疾病如何可能使一群孤立的昆蟲滅絕。","original_meaning":"滅絕","original_example":"Exterminate pests.","original_example_zh":"消滅害蟲。"},{"source_id":5095,"word":"extinguish","meaning":"撲滅","example":"The caretaker used a snuffer to extinguish the candle.","example_zh":"管理員用滅燭罩熄滅蠟燭。","original_meaning":"撲滅","original_example":"Extinguish the fire.","original_example_zh":"撲滅火勢。"},{"source_id":5096,"word":"falter","meaning":"動搖","example":"Her confidence began to falter when the model collapsed.","example_zh":"模型倒塌時，她的信心開始動搖。","original_meaning":"動搖","original_example":"Confidence faltered.","original_example_zh":"信心動搖了。"},{"source_id":5097,"word":"fathom","meaning":"理解","example":"He could not fathom how the tiny clock worked.","example_zh":"他無法理解這只小鐘如何運作。","original_meaning":"理解","original_example":"Cannot fathom why.","original_example_zh":"實在想不通為什麼。"},{"source_id":5098,"word":"forego","meaning":"放棄","example":"They chose to forego dessert and save room for the picnic.","example_zh":"他們選擇放棄甜點，留點胃口給野餐。","original_meaning":"放棄","original_example":"Forego the bonus.","original_example_zh":"放棄獎金。"},{"source_id":5099,"word":"innovate","meaning":"創新","example":"The students tried to innovate by reusing discarded materials.","example_zh":"學生嘗試透過再利用廢棄材料來創新。","original_meaning":"創新","original_example":"Constantly innovate.","original_example_zh":"不斷創新。"},{"source_id":5100,"word":"legislate","meaning":"立法","example":"The council planned to legislate for safer public buildings.","example_zh":"議會計畫立法，讓公共建築更安全。","original_meaning":"立法","original_example":"Legislate against pollution.","original_example_zh":"立法防治污染。"},{"source_id":5101,"word":"liquidate","meaning":"清算；變賣","example":"The company decided to liquidate its remaining inventory.","example_zh":"公司決定變賣剩餘存貨。","original_meaning":"清算","original_example":"Liquidate assets.","original_example_zh":"變現資產。"},{"source_id":5102,"word":"migrate","meaning":"遷移","example":"The birds migrate south when winter approaches.","example_zh":"冬季將近時，這些鳥會向南遷徙。","original_meaning":"遷移","original_example":"Birds migrate south.","original_example_zh":"鳥類向南遷徙。"},{"source_id":5103,"word":"neglect","meaning":"忽視","example":"He learned not to neglect the plants during the holidays.","example_zh":"他學會在假期中也不能忽略植物。","original_meaning":"忽視","original_example":"Neglect responsibilities.","original_example_zh":"忽視責任。"},{"source_id":5104,"word":"obstruct","meaning":"阻擋","example":"The fallen branch could obstruct the narrow path.","example_zh":"掉落的樹枝可能阻擋狹窄步道。","original_meaning":"阻擋","original_example":"Obstruct justice.","original_example_zh":"妨礙司法公正。"},{"source_id":5105,"word":"outweigh","meaning":"超過","example":"The benefits of the new library seemed to outweigh its costs.","example_zh":"新圖書館的好處似乎超過所需成本。","original_meaning":"超過","original_example":"Benefits outweigh risks.","original_example_zh":"利大於弊。"},{"source_id":5106,"word":"penalize","meaning":"處罰","example":"The referee can penalize a team for breaking the rules.","example_zh":"裁判可以因球隊違規而予以處罰。","original_meaning":"處罰","original_example":"Penalize offenders.","original_example_zh":"懲處違法者。"},{"source_id":5107,"word":"pertain","meaning":"有關","example":"These documents pertain to the town's old bridge.","example_zh":"這些文件與鎮上的古橋有關。","original_meaning":"有關","original_example":"Pertaining to the case.","original_example_zh":"與本案相關。"},{"source_id":5108,"word":"propagate","meaning":"傳播；繁殖","example":"The gardener showed us how to propagate the plant from a cutting.","example_zh":"園丁示範如何用枝條繁殖這種植物。","original_meaning":"傳播","original_example":"Propagate ideas.","original_example_zh":"傳播思想。"},{"source_id":5109,"word":"purge","meaning":"清除；清洗","example":"The editor decided to purge duplicate entries from the archive.","example_zh":"編輯決定清除檔案中的重複條目。","original_meaning":"清洗","original_example":"Purge the party.","original_example_zh":"淨化黨內。"},{"source_id":5110,"word":"rehabilitate","meaning":"復健","example":"The team worked to rehabilitate the injured animal before releasing it.","example_zh":"團隊努力讓受傷動物恢復健康，再將牠野放。","original_meaning":"復健","original_example":"Rehabilitate patients.","original_example_zh":"協助病患復健。"},{"source_id":5111,"word":"reimburse","meaning":"報銷","example":"The school agreed to reimburse the teacher for the art supplies.","example_zh":"學校同意報銷老師購買美術用品的費用。","original_meaning":"報銷","original_example":"Reimburse expenses.","original_example_zh":"報銷費用。"},{"source_id":5112,"word":"relegate","meaning":"貶降","example":"The coach decided to relegate the player to the reserve team.","example_zh":"教練決定把這名球員降到預備隊。","original_meaning":"貶降","original_example":"Relegated to second.","original_example_zh":"降級至第二名。"},{"source_id":5113,"word":"repress","meaning":"壓制","example":"She tried to repress a laugh during the serious speech.","example_zh":"她在嚴肅的演說中努力忍住笑。","original_meaning":"壓制","original_example":"Repress dissent.","original_example_zh":"壓制異議。"},{"source_id":5114,"word":"retaliate","meaning":"報復","example":"The captain urged the team not to retaliate after the foul.","example_zh":"隊長勸隊員在對方犯規後不要報復。","original_meaning":"報復","original_example":"Retaliate with force.","original_example_zh":"以武力報復。"},{"source_id":5115,"word":"stagnate","meaning":"停滯","example":"The project began to stagnate when the team stopped sharing ideas.","example_zh":"團隊不再分享想法時，專案開始停滯。","original_meaning":"停滯","original_example":"The economy stagnated.","original_example_zh":"經濟陷入停滯。"},{"source_id":5116,"word":"terminate","meaning":"終止","example":"The organizers decided to terminate the outdoor event because of heavy rain.","example_zh":"主辦方因大雨決定終止戶外活動。","original_meaning":"終止","original_example":"Terminate the contract.","original_example_zh":"終止合約。"},{"source_id":5117,"word":"testify","meaning":"作證","example":"The witness agreed to testify about what she had seen.","example_zh":"證人同意出庭說明她所見的情況。","original_meaning":"作證","original_example":"Testify under oath.","original_example_zh":"宣誓作證。"},{"source_id":5118,"word":"validate","meaning":"驗證","example":"The engineer ran a second experiment to validate the results.","example_zh":"工程師進行第二次實驗以驗證結果。","original_meaning":"驗證","original_example":"Validate the theory.","original_example_zh":"驗證該理論。"},{"source_id":5119,"word":"vandalize","meaning":"破壞公物","example":"The class discussed why it is wrong to vandalize public property.","example_zh":"全班討論破壞公共財物為何不對。","original_meaning":"破壞公物","original_example":"Vandalize the property.","original_example_zh":"破壞財產。"},{"source_id":5120,"word":"violate","meaning":"違反","example":"Parking here would violate the town's traffic rules.","example_zh":"在這裡停車會違反鎮上的交通規定。","original_meaning":"違反","original_example":"Violate the agreement.","original_example_zh":"違反協議。"},{"source_id":5121,"word":"withhold","meaning":"扣留","example":"The committee chose to withhold its decision until more evidence arrived.","example_zh":"委員會選擇等更多證據到齊再公布決定。","original_meaning":"扣留","original_example":"Withhold information.","original_example_zh":"隱瞞資訊。"},{"source_id":5124,"word":"administer","meaning":"管理","example":"The new director will administer the community center.","example_zh":"新主任將管理這座社區中心。","original_meaning":"管理","original_example":"Administer the program.","original_example_zh":"執行該計畫。"},{"source_id":5132,"word":"allege","meaning":"聲稱","example":"The reporter asked why the residents allege that the river is polluted.","example_zh":"記者詢問居民為何聲稱河川受到污染。","original_meaning":"聲稱","original_example":"Allegedly committed.","original_example_zh":"據稱已犯下。"},{"source_id":5134,"word":"alternate","meaning":"替代的；交替的","example":"We took an alternate route because the main road was closed.","example_zh":"主要道路封閉，所以我們改走另一條路。","original_meaning":"交替的","original_example":"On alternate days.","original_example_zh":"隔天一次。"},{"source_id":5135,"word":"amateur","meaning":"業餘者","example":"The amateur built a beautiful wooden birdhouse.","example_zh":"這位業餘愛好者做了一個漂亮的木製鳥屋。","original_meaning":"業餘者","original_example":"An amateur photographer.","original_example_zh":"一位業餘攝影師。"},{"source_id":5140,"word":"arouse","meaning":"喚起","example":"The unusual fossil began to arouse the students' curiosity.","example_zh":"這塊不尋常的化石開始引起學生的好奇心。","original_meaning":"喚起","original_example":"Arouse suspicion.","original_example_zh":"引起懷疑。"},{"source_id":5149,"word":"bind","meaning":"綁","example":"She used twine to bind the bundle of sticks.","example_zh":"她用麻繩綁起那捆木枝。","original_meaning":"綁","original_example":"Legally binding.","original_example_zh":"具有法律約束力。"},{"source_id":5150,"word":"blast","meaning":"爆炸；爆發","example":"The science exhibit showed a model of a volcanic blast.","example_zh":"科學展覽展示火山爆發的模型。","original_meaning":"爆炸","original_example":"A bomb blast.","original_example_zh":"一聲炸彈爆炸聲。"},{"source_id":5151,"word":"blur","meaning":"模糊","example":"The photographer used motion to blur the background.","example_zh":"攝影師利用移動讓背景模糊。","original_meaning":"模糊","original_example":"Blur the line.","original_example_zh":"模糊界線。"},{"source_id":5152,"word":"bureau","meaning":"局","example":"The tourism bureau offered maps to visitors.","example_zh":"觀光局提供地圖給遊客。","original_meaning":"局","original_example":"The FBI bureau.","original_example_zh":"聯邦調查局。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-gland-01-v1","level":"senior","word":"gland","sort_order":1,"sense":"腺體","alt_zh":"科學教室桌面特寫：不透明塑膠唾液腺教具，成年教師用指示棒講解，只有模型。","example":"The class examined a plastic model of a salivary gland.","example_zh":"全班觀察了唾液腺的塑膠模型。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/gland-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intestine-01-v1","level":"senior","word":"intestine","sort_order":1,"sense":"腸","alt_zh":"不透明塑膠消化系統教具，成年教師指出盤繞腸道，無真人身體。","example":"The teacher pointed to the intestine in the digestive system model.","example_zh":"老師指出消化系統模型中的腸道。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intestine-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-liver-01-v1","level":"senior","word":"liver","sort_order":1,"sense":"肝臟","alt_zh":"桌上不透明塑膠消化器官教具，學生指出深紅棕色肝臟部件，無人體。","example":"The student identified the liver on the classroom model.","example_zh":"學生在教室模型上辨認出肝臟。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/liver-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-kidney-01-v1","level":"senior","word":"kidney","sort_order":1,"sense":"腎臟","alt_zh":"科學展示桌上的不透明塑膠腎臟教具，豆形，旁有其他塑膠器官，無人體。","example":"The model showed a kidney beside the other organs.","example_zh":"模型展示了其他器官旁的一顆腎臟。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/kidney-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-lung-01-v1","level":"senior","word":"lung","sort_order":1,"sense":"肺","alt_zh":"成年科學教師從教具盒拿起不透明粉色塑膠肺模型，無人體。","example":"The teacher lifted a plastic lung from the teaching kit.","example_zh":"老師從教學套件中拿起一個塑膠肺模型。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/lung-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diabetes-01-v1","level":"senior","word":"diabetes","sort_order":1,"sense":"糖尿病","alt_zh":"成年護理師在明亮教室整理教材與血糖測量器展示品，不操作儀器，不呈現治療。","example":"The nurse prepared a lesson about diabetes.","example_zh":"護理師準備了一堂關於糖尿病的課。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diabetes-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-asthma-01-v1","level":"senior","word":"asthma","sort_order":1,"sense":"氣喘","alt_zh":"成年教師在健康教室展示不透明塑膠呼吸道模型，學生專注聆聽，無病患或發作。","example":"The health class discussed how asthma can affect daily life.","example_zh":"健康課討論氣喘如何影響日常生活。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/asthma-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-arthritis-01-v1","level":"senior","word":"arthritis","sort_order":1,"sense":"關節炎","alt_zh":"成年講師在桌面不透明膝關節模型旁講解，只有塑膠教具，無人體傷病。","example":"The lecturer used a joint model to explain arthritis.","example_zh":"講師用關節模型解釋關節炎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/arthritis-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dementia-01-v1","level":"senior","word":"dementia","sort_order":1,"sense":"失智","alt_zh":"社區講座中成年講師和成年家屬親切討論支持服務，桌上家庭相簿。","example":"The students learned about support for families affected by dementia.","example_zh":"學生了解了如何支持受失智症影響的家庭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dementia-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-obesity-01-v1","level":"senior","word":"obesity","sort_order":1,"sense":"肥胖","alt_zh":"圖書館明亮講堂，成年健康教育講師對穿普通服裝的成年聽眾講解，抽象圖表，尊重多元體型。","example":"The library hosted a public lecture about obesity.","example_zh":"圖書館舉辦了一場關於肥胖的公開講座。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/obesity-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-insomnia-01-v1","level":"senior","word":"insomnia","sort_order":1,"sense":"失眠","alt_zh":"成年女子夜間穿完整睡衣坐在臥室書桌寫日記，床未使用，安靜暖色檯燈。","example":"Her diary described several nights of insomnia.","example_zh":"她的日記描述了好幾晚的失眠。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/insomnia-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-migraine-01-v1","level":"senior","word":"migraine","sort_order":1,"sense":"偏頭痛","alt_zh":"穿完整休閒服的成年男子坐在診間向成年醫師說明狀況，桌上合上的筆電，無治療操作。","example":"He told the doctor that a migraine had interrupted his work.","example_zh":"他告訴醫師，偏頭痛打斷了他的工作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/migraine-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-stroke-01-v1","level":"senior","word":"stroke","sort_order":1,"sense":"中風","alt_zh":"成年醫學生在大學講堂聆聽教授，桌上不透明塑膠腦模型，無病患。","example":"The medical students attended a lecture about stroke.","example_zh":"醫學生參加了一堂關於中風的講課。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/stroke-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-tumor-01-v1","level":"senior","word":"tumor","sort_order":1,"sense":"腫瘤","alt_zh":"大學圖書館桌上的生物學書與抽象細胞模型，成年研究者閱讀，無病患與身體影像。","example":"The biology book included a chapter about tumor research.","example_zh":"生物學書籍有一章介紹腫瘤研究。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/tumor-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-infection-01-v1","level":"senior","word":"infection","sort_order":1,"sense":"感染","alt_zh":"成年實驗室團隊穿完整防護衣在封閉樣本盒旁觀察顯微鏡，無人體與病患。","example":"The laboratory team studied a sample for signs of infection.","example_zh":"實驗室團隊研究樣本是否有感染跡象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/infection-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inflammation-01-v1","level":"senior","word":"inflammation","sort_order":1,"sense":"發炎","alt_zh":"成年講師展示放大抽象細胞塑膠教具，模型上小紅色區塊，無真實組織。","example":"The lecturer explained inflammation with a simple model.","example_zh":"講師用簡單模型解釋發炎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inflammation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-painkiller-01-v1","level":"senior","word":"painkiller","sort_order":1,"sense":"止痛藥","alt_zh":"成年藥師在藥局櫃台檢查封閉無品牌藥盒，成年顧客詢問，沒有服藥或用量數字。","example":"The pharmacist checked the painkiller's label before answering her question.","example_zh":"藥師先查看止痛藥的標籤，再回答她的問題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/painkiller-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-symphony-01-v1","level":"senior","word":"symphony","sort_order":1,"sense":"交響曲","alt_zh":"音樂廳成年管弦樂團排練，指揮帶領弦樂管樂與打擊樂。","example":"The musicians rehearsed a symphony for the evening concert.","example_zh":"樂手們為晚間音樂會排練一首交響曲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/symphony-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ballet-01-v1","level":"senior","word":"ballet","sort_order":1,"sense":"芭蕾舞","alt_zh":"劇院舞台成年芭蕾舞